<script setup>
import { t, locale } from './i18n.js'
import {ref,onBeforeUnmount} from 'vue'
import { formatProxyOption } from './account-config.js'
const props=defineProps({api:{type:Function,required:true},busy:Boolean,contribution:Boolean,fixedProvider:String,token:String,proxies:{type:Array,default:()=>[]},proxyId:{type:Number,default:0},forceSendProxy:Boolean})
const provider=ref(props.fixedProvider||'openai'),verify=ref(true),selectedProxy=ref(0),items=ref([]),results=ref(null),error=ref('')
let epoch=0
async function choose(event){const current=++epoch;error.value='';items.value=[];results.value=null;const files=[...event.target.files];if(files.length>20||files.reduce((n,f)=>n+f.size,0)>1<<20){error.value=t('最多 20 个文件，总大小不超过 1 MiB');return}try{const loaded=await Promise.all(files.map(async file=>({name:file.name.replace(/\.json$/i,'').slice(0,128),auth:JSON.parse(await file.text())})));if(current===epoch)items.value=loaded}catch{error.value=t('授权文件必须是有效的 JSON，不会显示文件内容')}}
async function submit(){if(!items.value.length)throw new Error(t('请先选择授权文件'));const result=await props.api(props.contribution?'/contributions/import':'/admin/accounts/import',{method:'POST',body:props.contribution?{token:props.token,...((props.proxyId||props.forceSendProxy)?{proxy_id:props.proxyId}:{}),accounts:items.value}:{provider:provider.value,verify:verify.value,...(selectedProxy.value?{proxy_id:selectedProxy.value}:{}),accounts:items.value}});results.value=result;items.value=[];return result}
onBeforeUnmount(()=>{epoch++;items.value=[]})
defineExpose({submit,ready:()=>items.value.length>0,done:results})
</script>
<template>
 <div class="account-import"><p v-if="contribution" class="subtle">{{ t('请选择你自己的授权文件，服务器会加密保存。') }}</p><div v-else class="notice">{{ t('支持 Codex auth.json（tokens 字段）及含 access_token / refresh_token 的授权 JSON。只导入授权字段，不导入文件中的地址、代理或自定义请求头。文件内容不会展示或写入浏览器存储；服务器加密保存授权。') }}</div>
 <template v-if="!results"><fieldset :disabled="busy" class="config-section"><legend>{{ t('导入授权文件') }}</legend><p v-if="contribution" class="subtle">{{ t('供应商：') }}{{ {openai:'OpenAI Codex',claude:'Claude',antigravity:'Antigravity'}[provider] }}</p><label v-else>{{ t('导入供应商') }}<select :aria-label="t('导入供应商')" v-model="provider"><option value="openai">OpenAI Codex</option><option value="claude">Claude</option><option value="antigravity">Antigravity</option></select></label><label v-if="!contribution">{{ t('代理服务器') }}<select :aria-label="t('代理服务器')" v-model.number="selectedProxy"><option :value="0">{{ t('不使用代理（沿用部署环境默认）') }}</option><option v-for="p in proxies" :key="p.id" :value="p.id">{{ formatProxyOption(p,t) }}</option></select></label><label>{{ t('授权文件') }}<input type="file" :disabled="busy" :aria-label="t('授权文件')" accept=".json,application/json" multiple @change="choose"></label><label v-if="!contribution" class="checkbox"><input type="checkbox" v-model="verify">{{ t('导入后验证并同步模型') }}</label><p class="subtle">{{ t('最多 20 个 JSON 文件，总大小 1 MiB。') }}<template v-if="!contribution">{{ t('刷新令牌可能轮换，导入后应避免让多套服务同时刷新同一份授权。') }}</template></p><label v-for="(item,index) in items" :key="index">{{ t('账号名称') }} {{ index+1 }}<input v-model="item.name" :aria-label="t('导入账号名称 {0}',[index+1])" required maxlength="128"></label></fieldset></template>
 <div v-if="error" class="alert error" role="alert">{{ t(error) }}</div>
 <template v-if="results"><h3>{{ t(contribution?'已提交 {0} / {1} 个账号':'已导入 {0} / {1} 个账号',[results.imported,results.total]) }}</h3><p v-if="contribution&&results.imported" class="notice">{{ t('账号已提交，等待管理员配置并启用。') }}</p><div v-for="(item,index) in results.items" :key="index" class="import-result"><strong>{{ item.name }}</strong><span :class="['pill',{'bad-pill':!item.imported}]">{{ item.imported?t('已加密保存'):t('未导入') }}</span><p v-if="item.warning" class="subtle">{{ t(item.warning) }}</p><p v-else class="subtle">{{ contribution?t('已停用，等待管理员配置并启用'):verify?t('已同步 {0} 个模型',[item.models]):t('等待验证并同步') }}</p></div></template>
 </div>
</template>
